import { guideLesson } from './define.ts';
import type { Lesson } from './types.ts';
const G = (slug: string, title: string, prerequisites: string[], objectives: string[], sections: Lesson['sections'], question: string, options: string[], answer: number, explanation: string, optional = false): Lesson => guideLesson('gold', slug, { title, description: objectives.join(' · '), minutes: 35, prerequisites, objectives, sections, quiz: { question, options, answer, explanation }, optional });
export const goldLessons: Lesson[] = [
G('divisibility','Divisibilidad, primos y máximo común divisor',['usaco-bronze-time-comp'],['Descomponer números en factores primos','Justificar Euclides y una criba'],[
{title:'De repartir a demostrar',body:'Dos equipos pueden repartir 42 y 30 fichas en paquetes idénticos de seis. El máximo común divisor, mcd, describe el mayor tamaño permitido. Un número primo tiene exactamente dos divisores positivos. Cada entero mayor que uno posee una factorización prima única salvo el orden; esta propiedad convierte preguntas sobre divisores en preguntas sobre exponentes. Antes de programar, distingue encontrar un divisor, factorizar un número y listar todos los primos hasta un límite.'},
{title:'Ejemplo a mano',body:'Para 84 = 2² · 3 · 7 y 30 = 2 · 3 · 5, tomamos los exponentes menores para obtener mcd = 6. Los mayores producen mcm = 420. También mcm(a,b) = a / mcd(a,b) · b para enteros positivos. Euclides da mcd(84,30) = mcd(30,24) = mcd(24,6) = 6. El paso conserva los divisores comunes porque cualquier divisor de a y b divide a − qb, y el argumento funciona también en sentido contrario.'},
{title:'Dos herramientas concretas',body:'Euclides reemplaza el par por (b,a%b) hasta que b sea cero. Para muchos primos, la criba comienza suponiendo primos los enteros desde dos y marca múltiplos. Basta iniciar cada marcado en p²: los múltiplos menores ya tenían un factor primo menor. Si solo factorizas x, prueba divisores mientras d ≤ x/d y divide repetidamente; al terminar, un resto mayor que uno es primo.',code:'#include <iostream>\n#include <numeric>\nusing namespace std;\nint main(){ long long a,b; cin>>a>>b; cout<<gcd(a,b)<<"\\n"; }'},
{title:'Costo y práctica',body:'Euclides necesita O(log min(a,b)) operaciones; la división de prueba tarda O(√x) y una criba clásica O(N log log N) con O(N) memoria. Estas cotas cuentan operaciones aritméticas sobre enteros del tamaño admitido. No marques uno como primo ni calcules a*b antes de dividir si puede desbordar. Practica contando los divisores de 360: para 2³·3²·5, cada exponente se elige independientemente, así que hay 4·3·2 = 24 posibilidades.'}
],'¿Cuál es el mcd de 48 y 18?',['3','6','12','18'],1,'48 = 2·18 + 12 y 18 = 12 + 6; el último resto no nulo es 6.'),
G('modular','Aritmética modular y potencias rápidas',['usaco-gold-divisibility'],['Operar residuos sin perder información útil','Reconocer cuándo existe un inverso'],[
{title:'Trabajar con residuos',body:'En un reloj de doce horas, avanzar quince equivale a avanzar tres. Escribimos a ≡ b (mod m) cuando m divide a − b. Podemos sustituir números por sus residuos en sumas, restas y productos. Esto permite contar resultados enormes sin almacenarlos completos cuando el enunciado pide únicamente su residuo. El módulo debe permanecer fijo durante el cálculo; cambiarlo a mitad de una recurrencia destruye la interpretación.'},
{title:'Potencia por cuadrados',body:'Para calcular 3¹³ módulo 7, descompón 13 = 8 + 4 + 1. Los cuadrados sucesivos dan 3, 2, 4 y 2 como residuos de 3¹, 3², 3⁴ y 3⁸. Multiplicamos los seleccionados: 2·4·3 ≡ 3. El invariante del algoritmo es que resultado · base^exponente conserva la potencia original módulo m. En cada vuelta consumimos un bit del exponente y elevamos la base al cuadrado.',code:'#include <iostream>\nusing namespace std;\nint main(){ long long a,e,m; cin>>a>>e>>m; if(m<=0 || m>1000000007LL || e<0) return 0; a=(a%m+m)%m; long long r=1%m; while(e){ if(e&1) r=r*a%m; a=a*a%m; e>>=1; } cout<<r<<"\\n"; }'},
{title:'Dividir exige una condición',body:'No puedes dividir residuos como enteros. El inverso de a existe exactamente cuando mcd(a,m)=1. Por ejemplo, módulo 7 el inverso de 3 es 5 porque 3·5 ≡ 1. Si p es primo y a no es múltiplo de p, el pequeño teorema de Fermat permite calcularlo como a^(p−2). Módulo 8, el número 2 carece de inverso; ninguna potencia remedia esa ausencia.'},
{title:'Límites y comprobación',body:'La exponenciación usa O(log e) tiempo y O(1) memoria. El programa limita m para que multiplicar dos residuos quepa en long long; para módulos mayores necesitas multiplicación segura. En C++, un resto negativo puede ser negativo: normaliza con (x%m+m)%m. Prueba exponente cero, módulo uno y base negativa. Como ejercicio, demuestra que 10⁹ módulo 9 es uno y explica por qué dividir entre tres módulo nueve no está definido de manera única.'}
],'¿Qué número es inverso de 4 módulo 7?',['2','3','4','No existe'],0,'4·2 = 8 ≡ 1 (mod 7), así que multiplicar por 2 deshace la multiplicación por 4.'),
G('combo','Combinatoria: contar sin enumerar',['usaco-gold-modular'],['Distinguir elecciones ordenadas y conjuntos','Calcular coeficientes binomiales'],[
{title:'Elegir el objeto correcto',body:'Contar soluciones empieza por decidir cuándo dos resultados son diferentes. Elegir capitán y suplente entre cinco estudiantes tiene 5·4 resultados: los cargos distinguen el orden. Elegir dos representantes sin cargos tiene diez, porque cada pareja se había contado dos veces. La regla del producto sirve para decisiones sucesivas; la regla de la suma sirve para casos incompatibles que cubren todas las posibilidades.'},
{title:'La fórmula y su significado',body:'El coeficiente C(n,k) cuenta subconjuntos de tamaño k. La fórmula n!/(k!(n−k)!) elimina las permutaciones internas que no distinguen conjuntos. Para elegir tres de siete personas, 7·6·5/(3·2·1)=35. Otra explicación separa los equipos según incluyan a una persona elegida: C(n,k)=C(n−1,k−1)+C(n−1,k), con C(n,0)=C(n,n)=1. Esta recurrencia forma el triángulo de Pascal y no exige división.'},
{title:'Implementar según los límites',body:'Si necesitas todas las respuestas para n pequeño, llena Pascal por filas. Con un módulo primo p y n<p puedes precalcular factoriales e inversos factoriales en O(n + log p), y responder cada consulta en O(1). La condición n<p importa: n! sería cero módulo p cuando n≥p y ya no tendría inverso. El programa usa Pascal exacto para n≤60 y comprueba las fronteras.',code:'#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main(){ int n,k; cin>>n>>k; if(n<0||n>60||k<0||k>n) return 0; vector<long long> c(k+1); c[0]=1; for(int i=1;i<=n;i++) for(int j=min(i,k);j>=1;j--) c[j]+=c[j-1]; cout<<c[k]<<"\\n"; }'},
{title:'Evitar sobreconteos',body:'La versión de una fila cuesta O(nk) tiempo y O(k) espacio; recorre k hacia abajo para conservar la fila anterior. No uses factoriales en enteros comunes sin estimar su tamaño: 21! ya excede un entero con signo de 64 bits. Practica contando caminos de una esquina a otra de una cuadrícula con cuatro pasos a la derecha y dos hacia arriba. Cada camino corresponde a elegir las dos posiciones verticales entre seis, por lo que hay C(6,2)=15.'}
],'¿Cuántos equipos de dos se forman con seis estudiantes?',['12','15','30','36'],1,'Hay 6·5 parejas ordenadas; cada equipo aparece dos veces, así que 30/2=15.'),
G('intro-dp','Programación dinámica desde el estado',['usaco-bronze-complete-rec'],['Definir un estado con significado exacto','Construir recurrencias y casos base'],[
{title:'Recordar para no repetir',body:'La programación dinámica guarda respuestas a subproblemas que vuelven a aparecer. No basta con reconocer una tabla: necesitas definir qué significa cada entrada y por qué el pasado relevante cabe en ese estado. Imagina una escalera donde puedes subir uno o dos peldaños. Muchos recorridos llegan a la misma altura; desde ella las opciones futuras son idénticas, por lo que no es necesario recordar todo el recorrido.'},
{title:'Derivar la transición',body:'Define dp[i] como la cantidad de formas de llegar exactamente al peldaño i. El último salto mide uno o dos, de modo que dp[i]=dp[i−1]+dp[i−2]. Son casos disjuntos y exhaustivos. Fijamos dp[0]=1: existe un recorrido vacío. Para alturas 0,1,2,3,4 obtenemos 1,1,2,3,5. En cuatro peldaños, por ejemplo, aparecen 1111,112,121,211 y 22. Una buena recurrencia incluye explícitamente qué sucede en índices negativos.'},
{title:'Un orden que respeta dependencias',body:'La tabla ascendente funciona porque i solo depende de posiciones menores. También puedes usar recursión con memoria, siempre que marques qué estados ya calculaste. Si aparecen ciclos entre estados, esta receta no basta: debes cambiar la representación o estudiar otro algoritmo. El programa acepta hasta 90 peldaños para mantener el resultado exacto dentro de long long; en problemas mayores podría solicitarse una respuesta modular.',code:'#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){ int n; cin>>n; if(n<0||n>90) return 0; vector<long long> dp(n+1); dp[0]=1; for(int i=1;i<=n;i++){ dp[i]=dp[i-1]; if(i>=2) dp[i]+=dp[i-2]; } cout<<dp[n]<<"\\n"; }'},
{title:'Medir y generalizar',body:'El tiempo es número de estados por trabajo de cada transición: aquí O(n), con O(n) memoria, reducible a dos valores anteriores. No confundas contar formas con minimizar costo: al minimizar normalmente usarías infinito para estados imposibles y un mínimo entre candidatos. Como ejercicio, prohíbe el tercer peldaño y calcula las formas de llegar al quinto. Debes forzar dp[3]=0; los valores posteriores se vuelven 2 y 2, mostrando que las condiciones del estado afectan el conteo.'}
],'¿Cuántas formas hay de subir cinco peldaños con saltos de uno o dos?',['5','6','8','10'],2,'dp[3]=3 y dp[4]=5; el último salto separa los recorridos y dp[5]=3+5=8.'),
G('knapsack','Mochila y elecciones con capacidad',['usaco-gold-intro-dp'],['Diseñar estados de capacidad o valor','Separar mochila 0/1 e ilimitada'],[
{title:'Una decisión por objeto',body:'Tienes una mochila con capacidad W y objetos con peso y valor. En la variante 0/1 puedes tomar cada objeto a lo sumo una vez. Define dp[i][w] como el mayor valor usando los primeros i objetos con peso total a lo sumo w. La decisión sobre el objeto i divide las soluciones entre no tomarlo y tomarlo si cabe. Esa separación convierte una búsqueda de subconjuntos en una tabla.'},
{title:'Ejemplo y recurrencia',body:'Con objetos (peso,valor) = (2,3), (3,4), (4,5) y capacidad cinco, la mejor elección es los dos primeros, de valor siete. La transición compara dp[i−1][w] con dp[i−1][w−peso_i]+valor_i. Si usamos solo una fila, debemos recorrer capacidades de W hacia peso_i: así dp[w−peso_i] aún representa los objetos anteriores. Recorrer hacia arriba permitiría usar repetidamente el mismo objeto y resolvería otro problema.'},
{title:'Programa completo',body:'El código lee n y W seguidos de n pares peso,valor. Inicializar toda la fila a cero representa capacidad máxima disponible, no peso exacto. Para exigir peso exactamente W, inicia solo dp[0]=0 y los demás como imposibles. Cuando los pesos son gigantes pero la suma de valores es pequeña, invierte la definición: guarda el peso mínimo necesario para obtener cada valor.',code:'#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main(){ int n,W; cin>>n>>W; vector<long long> dp(W+1); for(int i=0;i<n;i++){ int w; long long v; cin>>w>>v; for(int c=W;c>=w;c--) dp[c]=max(dp[c],dp[c-w]+v); } cout<<dp[W]<<"\\n"; }'},
{title:'Una cota que depende del número',body:'La mochila clásica tarda O(nW) y usa O(W) memoria. Es seudopolinomial: W puede ser enorme respecto a la cantidad de bits que lo representan, así que revisa límites antes de elegirla. Asume pesos no negativos y capacidad representable; con objetos ilimitados de peso cero y valor positivo el óptimo no sería finito. Practica el ejemplo con capacidad seis: el objeto de peso dos junto con el de peso cuatro logra valor ocho. Explica por qué ordenar por valor/peso no garantiza una solución 0/1 óptima.'}
],'Al procesar un objeto 0/1 en una sola fila, ¿cómo recorres capacidades?',['De menor a mayor','De mayor a menor','En cualquier orden'],1,'Descender evita que dp[w−peso] haya incorporado ya el mismo objeto en esa iteración.'),
G('paths-grids','Caminos y estados en cuadrículas',['usaco-gold-intro-dp'],['Contar caminos con obstáculos','Reconocer una cuadrícula como DAG'],[
{title:'Cada celda resume un viaje',body:'Supón que una persona se mueve solo a la derecha o hacia abajo en un mapa rectangular. El orden de filas y columnas impide regresar a una celda anterior, así que las dependencias forman un grafo dirigido sin ciclos. Define dp[f][c] como la cantidad de caminos desde el origen hasta esa celda. Un obstáculo elimina todos los caminos que intentarían terminar allí, aunque existan rutas a sus vecinos.'},
{title:'Un mapa pequeño',body:'En una cuadrícula de 3 por 3 sin obstáculos hay seis caminos. Si bloqueas el centro, la primera fila y primera columna siguen valiendo uno, el centro vale cero y las dos celdas junto al destino valen uno. El destino recibe 1+1=2. La fórmula es dp[f][c]=dp[f−1][c]+dp[f][c−1] para celdas libres. El origen vale uno si está libre y cero si está bloqueado; no lo inicialices incondicionalmente.'},
{title:'Reutilizar una fila',body:'Cuando avanzas de izquierda a derecha, dp[c] contiene la respuesta de arriba y dp[c−1] la respuesta ya actualizada de la izquierda. Esta interpretación permite usar O(columnas) memoria. El programa lee dimensiones y filas con punto para libre y numeral para obstáculo, y cuenta módulo 1000000007. El mismo esquema puede minimizar costos, pero entonces reemplazas la suma de caminos por el mínimo de costos más el costo de entrar.',code:'#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\nint main(){ int n,m; cin>>n>>m; vector<long long> dp(m); for(int r=0;r<n;r++){ string s; cin>>s; for(int c=0;c<m;c++){ if(s[c]==\'#\') dp[c]=0; else if(r==0&&c==0) dp[c]=1; else if(c) dp[c]=(dp[c]+dp[c-1])%1000000007; } } cout<<dp[m-1]<<"\\n"; }'},
{title:'Condiciones y ejercicio',body:'El tiempo es O(filas·columnas), adecuado si realmente puedes visitar cada celda. Si el tablero tiene coordenadas enormes y pocos obstáculos, necesitarás combinatoria u otra compresión. Permitir movimientos hacia arriba crea ciclos y rompe el orden empleado; para distancias uniformes convendría BFS. Practica en un tablero 2 por 4 con la segunda celda de la primera fila bloqueada: solo puedes bajar inmediatamente y después avanzar, así que queda un camino. Comprueba también un tablero de una sola celda.'}
],'En un tablero 2×3 libre con movimientos derecha/abajo, ¿cuántos caminos hay?',['2','3','4','6'],1,'Cada camino tiene dos movimientos a la derecha y uno hacia abajo. Elegir la posición del movimiento vertical da tres posibilidades.'),
G('lis','Subsecuencia creciente más larga',['usaco-gold-intro-dp','usaco-silver-binary-search-sorted-array'],['Distinguir subsecuencia de subarreglo','Mantener finales óptimos con búsqueda binaria'],[
{title:'Puedes saltarte posiciones',body:'Una subsecuencia conserva el orden original pero permite eliminar elementos. En [3,1,2,5,4], [1,2,4] es creciente aunque sus posiciones no sean consecutivas. Define primero dp[i] como la longitud máxima de una subsecuencia estrictamente creciente que termina exactamente en i. La recurrencia es uno más el máximo dp[j] entre j<i con a[j]<a[i], o uno si no existe tal j. Esta definición O(n²) sirve para comprender y verificar soluciones rápidas.'},
{title:'Guardar el final más prometedor',body:'Mantén tails[k] como el menor valor final posible para una subsecuencia de longitud k+1. Un final pequeño deja más opciones futuras. Al procesar 3,1,2,5,4, la lista evoluciona [3], [1], [1,2], [1,2,5], [1,2,4]. Su tamaño final es tres. La lista de finales no necesariamente constituye una subsecuencia real: cada posición puede provenir de decisiones históricas distintas. Para recuperar el recorrido debes guardar predecesores e índices.'},
{title:'Por qué funciona la búsqueda',body:'Los finales están estrictamente ordenados. Para un nuevo x, sustituye el primer final mayor o igual que x usando lower_bound, o agrégalo si no existe. Esto mejora el final sin cambiar las longitudes previamente alcanzables. Si buscas una subsecuencia no decreciente, utiliza upper_bound, el primer valor estrictamente mayor, porque los iguales sí pueden extender una subsecuencia. El programa imprime solamente la longitud estrictamente creciente.',code:'#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main(){ int n; cin>>n; vector<long long> t; while(n--){ long long x; cin>>x; auto p=lower_bound(t.begin(),t.end(),x); if(p==t.end()) t.push_back(x); else *p=x; } cout<<t.size()<<"\\n"; }'},
{title:'Complejidad y trampas',body:'Cada elemento realiza una búsqueda O(log n), dando O(n log n) tiempo y O(n) espacio. Ordenar la entrada no es una optimización válida: destruiría precisamente la condición de orden original. Prueba [2,2,2], cuya respuesta estricta es uno y cuya respuesta no decreciente es tres. Como ejercicio, adapta la versión cuadrática para contar cuántas subsecuencias de longitud máxima existen. Necesitarás combinar longitudes y cantidades, no basta con observar el tamaño de tails.'}
],'¿Cuál es la LIS estricta de [4,1,2,2,3]?',['2','3','4','5'],1,'La subsecuencia [1,2,3] tiene longitud tres; usar ambos doses violaría el crecimiento estricto.'),
G('dp-bitmasks','DP con máscaras de bits',['usaco-gold-intro-dp','usaco-silver-intro-bitwise'],['Representar conjuntos pequeños como enteros','Separar estado visitado y último elemento'],[
{title:'Un bit por decisión',body:'Cuando n ronda veinte, una máscara de n bits permite representar cualquier subconjunto. El bit i vale uno si el elemento i está incluido. Esta representación no reduce los 2^n conjuntos existentes, pero vuelve compactas las operaciones de pertenencia, inserción y eliminación. Una DP puede compartir resultados entre órdenes diferentes que llegan al mismo conjunto, siempre que el futuro dependa solo de la información guardada.'},
{title:'Asignaciones como primer modelo',body:'Hay tres estudiantes y tres tareas. Sea dp[mask] el número de formas de asignar las primeras popcount(mask) personas a las tareas marcadas. Partimos de dp[0]=1. Para cada tarea libre compatible con la siguiente persona, sumamos dp[mask] a dp[mask | (1<<tarea)]. Si todas las asignaciones están permitidas, las máscaras de un bit tienen uno, las de dos bits tienen dos y la máscara 111 termina con seis, que coincide con 3!.'},
{title:'Cuando falta el último vértice',body:'Para contar caminos hamiltonianos en un grafo, el conjunto visitado no basta: necesitas saber dónde termina el camino. Usa dp[mask][v]. Desde un estado válido, agrega un vecino u no visitado y acumula en dp[mask|(1<<u)][u]. Si todos los caminos comienzan en s, inicializa únicamente dp[1<<s][s]=1. El invariante afirma que cada secuencia contada usa exactamente los vértices de mask y termina en v, evitando mezclar caminos incompatibles.'},
{title:'Límites reales y práctica',body:'La asignación cuesta O(n·2^n) tiempo y O(2^n) memoria. La transición densa de caminos puede costar O(n²·2^n) y memoria O(n·2^n), que crece rápidamente. No reserves esta tabla para n=40. Usa tipos sin signo o tamaños seguros al desplazar bits; un desplazamiento igual al ancho del tipo es inválido. Como ejercicio, restringe a la primera persona para que solo haga tarea cero: quedan dos asignaciones completas. Deriva también una versión que minimice costos reemplazando suma por mínimo.'}
],'En dp[mask] para asignaciones, ¿qué persona se asigna a continuación?',['La de índice popcount(mask)','La de índice mask','Siempre la última'],0,'Los bits cuentan tareas ya ocupadas; se ha asignado exactamente esa misma cantidad de personas iniciales.'),
G('dp-ranges','Programación dinámica en intervalos',['usaco-gold-intro-dp','usaco-silver-prefix-sums'],['Definir estados sobre segmentos contiguos','Elegir el último corte o la última operación'],[
{title:'El subproblema tiene dos fronteras',body:'En problemas donde solo puedes combinar elementos contiguos, un estado natural es dp[l][r]: la mejor respuesta para el intervalo de l a r. No cualquier pareja de índices funciona automáticamente; debes demostrar que, fijadas las fronteras, no necesitas saber cómo se resolvió el exterior. Los problemas de fusionar montones, parentizar productos y juegos sobre extremos suelen compartir esta estructura aunque sus transiciones sean distintas.'},
{title:'Fusionar montones',body:'Tenemos montones de tamaños [2,3,4]. Fusionar dos vecinos cuesta la suma de sus tamaños. Si primero unes 2 y 3, pagas cinco y después nueve: total catorce. Si unes 3 y 4 primero, pagas siete y luego nueve: total dieciséis. Sea S(l,r) la suma del intervalo. El último paso une [l,k] y [k+1,r], así que dp[l][r]=min_k(dp[l][k]+dp[k+1][r]+S(l,r)). Para un solo montón el costo es cero.'},
{title:'Ordenar por longitud',body:'Llena primero intervalos de longitud uno, luego dos y así sucesivamente. Todos los intervalos usados por la transición son más cortos que el actual; esa es la prueba de que ya están disponibles. Un arreglo de prefijos calcula S(l,r) en O(1). Para reconstruir las fusiones, guarda el corte k que logró cada mínimo y recorre ambos subintervalos. Empates pueden resolverse con cualquier regla consistente si solo piden un óptimo.'},
{title:'Costo, supuestos y siguiente reto',body:'Hay O(n²) estados y hasta O(n) cortes por estado: O(n³) tiempo y O(n²) memoria. La restricción de contigüidad es esencial: permitir fusionar cualquier par conduce a otro problema. No apliques una optimización de cortes monótonos sin probar sus condiciones, aunque ejemplos pequeños la sugieran. Practica [1,1,1,1]: fusionar parejas cuesta 2+2 y unirlas cuesta cuatro, total ocho. Compara con fusionar siempre desde la izquierda, que cuesta 2+3+4=9, para descartar esa regla voraz.'}
],'Para fusionar [2,3,4], ¿cuál es el costo óptimo?',['9','12','14','16'],2,'Fusionar 2 y 3 cuesta 5; fusionar el montón de 5 con 4 cuesta 9. Total 14.'),
G('digit-dp','DP por dígitos y límites numéricos',['usaco-gold-intro-dp'],['Contar enteros sin recorrer el rango','Controlar prefijos ajustados y ceros iniciales'],[
{title:'Construir números de izquierda a derecha',body:'Si te piden cuántos enteros hasta 10¹⁸ cumplen una propiedad, recorrerlos es imposible pero cada uno tiene pocas cifras. La DP por dígitos construye prefijos y reúne aquellos con el mismo comportamiento futuro. Un estado suele incluir posición, información de la propiedad y tight: si el prefijo coincide todavía con el del límite. También puede incluir started para distinguir ceros iniciales de dígitos pertenecientes al número.'},
{title:'Un ejemplo que puedes enumerar',body:'Cuenta enteros entre cero y 25 cuya suma de cifras es múltiplo de tres. El estado lleva el residuo de la suma módulo tres. Las respuestas son 0,3,6,9,12,15,18,21,24: nueve números. Si eliges primera cifra uno, ya eres menor que el prefijo dos del límite y la segunda cifra puede ser cualquiera. Si eliges dos, tight sigue activo y la segunda cifra solo puede ir de cero a cinco.'},
{title:'Recurrencia completa',body:'Define F(pos,residuo,tight) como el número de terminaciones válidas del prefijo. El máximo dígito permitido es la cifra del límite si tight vale verdadero, o nueve en caso contrario. Para cada d, suma F(pos+1,(residuo+d)%3,tight && d==cifraDelLímite). Al agotar posiciones devuelve uno si residuo es cero y cero si no. Para esta propiedad los ceros iniciales son inocuos; para contar números que contienen el dígito cero debes agregar started y tratar el número cero explícitamente.'},
{title:'Rangos y errores frecuentes',body:'Con L cifras y S estados de la propiedad, el costo es O(L·S·10), multiplicado por pequeñas banderas, y memoria O(L·S). Un intervalo [a,b] se resuelve como contar(b)−contar(a−1), definiendo contar(x)=0 para x<0. No reutilices estados tight entre límites distintos sin limpiar la memoria. Practica contar hasta 25 números sin dígitos consecutivos iguales: los ceros de relleno no deben hacer inválidos los números de una cifra. Comprueba primero todos los números hasta cien con una solución exhaustiva.'}
],'Si el prefijo elegido ya es menor que el del límite, ¿qué ocurre con tight?',['Vuelve a verdadero en la siguiente cifra','Permanece falso','Impide elegir cero'],1,'Una diferencia en una cifra más significativa ya garantiza que todo sufijo produce un número menor.'),
G('unweighted-shortest-paths','BFS y caminos con pesos cero o uno',['usaco-silver-graph-traversal'],['Probar la distancia mínima por capas','Elegir cola o deque según los pesos'],[
{title:'Explorar distancias crecientes',body:'En un grafo donde cada arista cuesta uno, BFS visita primero la fuente, después todos los vértices a distancia uno, luego a distancia dos. Una cola conserva este orden de capas. Define dist[v]=−1 para no visitado y dist[s]=0. Cuando descubres u desde v, asigna dist[u]=dist[v]+1 y encola u. Marca al descubrir, no al extraer, para evitar que varios vecinos encolen repetidamente el mismo vértice.'},
{title:'Seguir una ruta concreta',body:'Con aristas 0–1, 0–2, 1–3, 2–3 y 3–4, las capas son {0}, {1,2}, {3}, {4}. La distancia de cero a cuatro es tres. Guarda padre[u]=v cuando lo descubres y retrocede desde el destino para recuperar una ruta. Puede haber varias rutas mínimas y BFS devolverá una según el orden de adyacencia. La prueba consiste en observar que ninguna arista desde una capa futura puede mejorar una distancia ya asignada.'},
{title:'Implementación y extensión',body:'El programa lee n, m y aristas no dirigidas con índices desde cero, y muestra las distancias desde cero. Si hay varias fuentes, inicializa todas con distancia cero en la misma cola. Para aristas de costo cero o uno, usa 0–1 BFS: relaja distancias, coloca mejoras por costo cero al frente de una deque y por costo uno al fondo. La primera visita simple ya no sustituye a una relajación.',code:'#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main(){ int n,m; cin>>n>>m; vector<vector<int>> g(n); while(m--){ int a,b; cin>>a>>b; g[a].push_back(b); g[b].push_back(a); } vector<int>d(n,-1); queue<int>q; d[0]=0; q.push(0); while(!q.empty()){ int v=q.front(); q.pop(); for(int u:g[v]) if(d[u]==-1){ d[u]=d[v]+1; q.push(u); } } for(int x:d) cout<<x<<" "; cout<<"\\n"; }'},
{title:'Costo y modelado',body:'Con listas de adyacencia, BFS cuesta O(n+m) tiempo y O(n+m) memoria incluyendo el grafo; 0–1 BFS también admite tiempo lineal. No uses BFS ordinario para costos arbitrarios: una ruta con menos aristas puede ser más cara. Practica modelando un tablero como grafo implícito y una llave como estado adicional: (fila,columna,tieneLlave). Dos visitas a la misma celda con distinta llave son estados distintos porque ofrecen movimientos futuros diferentes.'}
],'En el ejemplo, ¿qué distancia tiene el vértice 4 desde 0?',['2','3','4'],1,'Se necesita llegar a 1 o 2, después a 3 y después a 4: tres aristas.'),
G('dsu','Conjuntos disjuntos y conectividad',['usaco-silver-graph-traversal'],['Mantener componentes al agregar conexiones','Usar tamaño y compresión de caminos'],[
{title:'Preguntar quién pertenece al mismo grupo',body:'Una estructura de conjuntos disjuntos, DSU, mantiene una partición de elementos. find(v) devuelve un representante del grupo de v y unite(a,b) combina dos grupos. No conserva las aristas ni describe una ruta entre vértices: solo responde pertenencia a componentes. Funciona especialmente bien cuando las conexiones se agregan y las componentes solo se fusionan. Quitar una arista puede dividir un grupo y requiere técnicas adicionales.'},
{title:'Ejemplo de conexiones',body:'Comienza con cinco estudiantes separados. Agrega 0–1 y 2–3: quedan {0,1}, {2,3}, {4}. Agrega 1–2 y obtienes {0,1,2,3}, {4}. Una nueva conexión 0–3 no reduce la cantidad de componentes porque sus representantes ya coinciden. El invariante es que cada conjunto forma un árbol de padres cuya raíz es su representante. La identidad numérica de la raíz no importa; no supongas que será el menor elemento.'},
{title:'Dos mejoras compatibles',body:'Unir por tamaño coloca la raíz del grupo menor bajo la del mayor y actualiza el tamaño. La compresión de caminos conecta cada vértice visitado por find directamente con la raíz encontrada. Ambas preservan la partición aunque cambien la forma interna del árbol. El programa recibe n y m conexiones y muestra cuántas componentes quedan. El valor de size solo es fiable en las raíces.',code:'#include <iostream>\n#include <vector>\n#include <numeric>\n#include <algorithm>\nusing namespace std;\nstruct DSU{ vector<int>p,s; DSU(int n):p(n),s(n,1){iota(p.begin(),p.end(),0);} int find(int x){return p[x]==x?x:p[x]=find(p[x]);} bool join(int a,int b){a=find(a);b=find(b);if(a==b)return false;if(s[a]<s[b])swap(a,b);p[b]=a;s[a]+=s[b];return true;} };\nint main(){int n,m;cin>>n>>m;DSU d(n);int components=n;while(m--){int a,b;cin>>a>>b;components-=d.join(a,b);}cout<<components<<"\\n";}'},
{title:'Amortización y aplicaciones',body:'Con ambas mejoras, una secuencia de operaciones cuesta O((n+m)α(n)), donde α es la inversa de Ackermann y crece extremadamente despacio. El espacio adicional es O(n). Es una cota amortizada, no una promesa de exactamente una operación por consulta. Practica detectando la primera arista que crea un ciclo en un grafo no dirigido: ocurre cuando sus extremos ya estaban conectados. Explica por qué esa prueba no detecta del mismo modo ciclos dirigidos, pues la conectividad ignora la orientación.'}
],'Después de unir 0–1, 2–3 y 1–2 en cinco elementos, ¿cuántos grupos quedan?',['1','2','3','4'],1,'Los cuatro primeros elementos forman un grupo y el elemento 4 permanece solo: dos grupos.'),
G('toposort','Orden topológico y DP en DAG',['usaco-silver-graph-traversal','usaco-gold-intro-dp'],['Ordenar tareas con dependencias','Detectar ciclos y propagar estados'],[
{title:'Dependencias antes de resultados',body:'Si aprender bucles exige conocer variables, la lección de variables debe aparecer antes. Un orden topológico acomoda los vértices de un grafo dirigido de modo que toda arista vaya hacia adelante. Existe exactamente cuando el grafo no tiene ciclos dirigidos. Puede haber muchos órdenes válidos; el algoritmo no necesita elegir uno único salvo que el problema pida, por ejemplo, el menor lexicográficamente.'},
{title:'Eliminar lo que ya está listo',body:'Kahn mantiene el grado de entrada de cada vértice. Encola todos los que no tienen requisitos pendientes. Al extraer v, lo agrega al orden y reduce los grados de sus sucesores; los que llegan a cero pasan a estar disponibles. Con aristas 0→2, 1→2, 2→3, puedes producir 0,1,2,3 o 1,0,2,3. Si hay un ciclo 2→3→2, ninguno de sus vértices puede quedar listo después de quitar todos los requisitos externos.'},
{title:'Programa y aplicaciones',body:'El programa imprime un orden válido o CICLO si no procesa todos los vértices. Sobre el orden puedes contar caminos con ways[u]+=ways[v] para cada arista v→u, o hallar la mayor longitud con best[u]=max(best[u],best[v]+1). Debes inicializar la fuente según el problema; poner uno en todos los vértices cuenta caminos que empiezan en cualquiera, que es otra pregunta.',code:'#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;vector<vector<int>>g(n);vector<int>in(n),order;while(m--){int a,b;cin>>a>>b;g[a].push_back(b);in[b]++;}queue<int>q;for(int i=0;i<n;i++)if(!in[i])q.push(i);while(!q.empty()){int v=q.front();q.pop();order.push_back(v);for(int u:g[v])if(--in[u]==0)q.push(u);}if((int)order.size()!=n)cout<<"CICLO\\n";else{for(int v:order)cout<<v<<" ";cout<<"\\n";}}'},
{title:'Costo y errores a evitar',body:'Construir el orden cuesta O(n+m) y usa O(n+m) memoria incluyendo las aristas. La DP adicional también es lineal si cada transición cuesta constante. Un grafo puede tener ciclos en una componente desconectada: procesar desde una sola fuente no basta para certificar que todo el grafo es DAG. Como ejercicio, agrega 0→3 al ejemplo y cuenta caminos de cero a tres: hay dos, el directo y el que pasa por dos. Después añade 3→0 y explica por qué desaparece cualquier orden válido.'}
],'Si Kahn procesa solo 7 de 10 vértices, ¿qué concluyes?',['El grafo tiene un ciclo dirigido','Los tres restantes están aislados','Se necesita DFS para decidir'],0,'Todo DAG no vacío tiene un vértice de entrada cero. Si quedan vértices y ninguno está listo, hay un ciclo dirigido.'),
G('shortest-paths','Dijkstra y rutas con pesos',['usaco-gold-unweighted-shortest-paths','usaco-silver-priority-queues'],['Relajar aristas ponderadas','Justificar la condición de pesos no negativos'],[
{title:'Distancia no significa número de pasos',body:'Dos carreteras cortas pueden costar menos que una sola carretera larga. Para pesos no negativos, Dijkstra mantiene distancias tentativas y elige siempre el vértice pendiente con menor valor. La operación fundamental es relajar v→u: si dist[v]+peso mejora dist[u], actualizamos la estimación. Una cola de prioridad permite encontrar rápidamente el siguiente candidato sin revisar todos los vértices cada vez.'},
{title:'Un ejemplo decisivo',body:'Con 0→1 de peso cinco, 0→2 de peso uno y 2→1 de peso dos, empezamos con distancias [0,5,1]. Sacamos el vértice dos antes que el uno y mejoramos dist[1] a tres. La ruta óptima no es la de una sola arista. La prueba usa pesos no negativos: cualquier ruta alternativa que atraviese un vértice todavía más lejano no puede regresar con una distancia menor al mínimo extraído.'},
{title:'Entradas viejas en el montículo',body:'Una implementación sencilla agrega un nuevo par cada vez que mejora una distancia y conserva los pares antiguos. Al sacar (d,v), si d no coincide con dist[v], lo ignora. Esto evita procesar de nuevo todas las aristas de una estimación obsoleta. El programa usa un grafo dirigido y supone que todos los pesos son no negativos y las distancias relevantes menores que 4·10¹⁸.',code:'#include <iostream>\n#include <vector>\n#include <queue>\n#include <functional>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;using P=pair<long long,int>;vector<vector<P>>g(n);while(m--){int a,b;long long w;cin>>a>>b>>w;g[a].push_back({w,b});}const long long INF=4000000000000000000LL;vector<long long>d(n,INF);priority_queue<P,vector<P>,greater<P>>q;d[0]=0;q.push({0,0});while(!q.empty()){auto [x,v]=q.top();q.pop();if(x!=d[v])continue;for(auto [w,u]:g[v])if(w<=INF-x && x+w<d[u]){d[u]=x+w;q.push({d[u],u});}}for(auto x:d)cout<<(x==INF?-1:x)<<" ";cout<<"\\n";}'},
{title:'Escoger el algoritmo correcto',body:'Con montículo binario y entradas duplicadas, el tiempo es O((n+m)log(n+m)) y la memoria O(n+m). Para un grafo simple se suele expresar O((n+m)log n). Pesos negativos rompen la prueba, aunque no exista ciclo negativo. En DAG puedes calcular distancias en orden topológico incluso con pesos negativos; para grafos generales estudia Bellman–Ford. Practica agregando 1→3 con peso cuatro y 2→3 con peso diez: la mejor distancia a tres es siete, pasando por dos y uno.'}
],'¿Qué condición exige la prueba habitual de Dijkstra?',['Pesos todos distintos','Pesos no negativos','Grafo sin ciclos','Una sola ruta por vértice'],1,'Los pesos no negativos impiden que continuar una ruta desde una distancia mayor produzca una distancia total menor.'),
G('mst','Árbol de expansión mínima',['usaco-gold-dsu','usaco-silver-greedy-sorting'],['Distinguir conectar todo de hallar rutas cortas','Justificar Kruskal mediante cortes'],[
{title:'Conectar pagando una sola vez',body:'Una red de escuelas necesita quedar conectada con el menor costo total de cable. El objetivo suma las aristas elegidas, no las distancias desde una escuela. En un grafo no dirigido y conectado, una solución óptima puede ser un árbol de expansión con n−1 aristas. Si una solución incluye un ciclo, se puede eliminar una de sus aristas sin perder conectividad; con costos no negativos esto nunca empeora el costo.'},
{title:'Kruskal en un triángulo',body:'Para tres vértices con aristas de pesos 2,3,7, ordenamos y elegimos primero la arista dos, luego la tres. La siete formaría un ciclo y se descarta. El total óptimo es cinco. Kruskal procesa aristas en orden creciente y agrega una cuando une componentes distintas del DSU. La propiedad del corte justifica la elección: una arista mínima que cruza entre una componente actual y el resto puede pertenecer a algún árbol óptimo compatible con lo ya seleccionado.'},
{title:'Prueba por intercambio',body:'Imagina un árbol óptimo que no contiene una arista e elegida por Kruskal. Al agregar e aparece un ciclo. Ese ciclo contiene otra arista f que cruza el mismo corte; por la elección mínima, peso(e)≤peso(f). Sustituir f por e mantiene un árbol y no aumenta su costo. Repetir este intercambio demuestra que las decisiones voraces pueden extenderse a un óptimo. Los empates pueden producir árboles diferentes con el mismo costo, lo cual es completamente válido.'},
{title:'Complejidad y fronteras',body:'Ordenar domina el tiempo O(m log m); DSU añade O(mα(n)) y se requiere O(n+m) memoria. Si al terminar hay menos de n−1 aristas elegidas, el grafo no era conectado y obtuviste un bosque mínimo. Los pesos negativos también son compatibles con Kruskal cuando buscamos un árbol; la explicación de eliminar ciclos de una red arbitraria debe matizarse entonces. Practica un cuadrado con lados de peso uno y diagonales de peso diez: cualquier selección de tres lados que conecte los cuatro vértices cuesta tres. Comprueba que su ruta entre dos vértices no necesariamente coincide con la ruta mínima del grafo original.'}
],'¿Cuántas aristas tiene un árbol de expansión de ocho vértices?',['6','7','8','Depende de los pesos'],1,'Todo árbol conectado de n vértices tiene n−1 aristas; para ocho son siete.'),
G('intro-sorted-sets','Conjuntos ordenados y búsquedas por vecino',['usaco-bronze-intro-sets','usaco-silver-binary-search-sorted-array'],['Usar set y multiset con límites','Elegir una estructura según las operaciones'],[
{title:'Un orden que se mantiene solo',body:'Un set mantiene elementos distintos en orden, mientras un multiset permite repeticiones. Ambos soportan insertar, encontrar y eliminar sin ordenar todo nuevamente. Son útiles para localizar el primer valor al menos x, su predecesor o el mínimo actual mientras llegan cambios. No confundir este orden con el orden de inserción: el recorrido de un set sigue su comparador, aunque los elementos hayan llegado de manera diferente.'},
{title:'Asignar boletos',body:'Dispones de precios [3,5,5,8] y una persona puede pagar hasta seis. En el multiset, upper_bound(6) apunta a ocho; su predecesor es cinco, el boleto más caro que aún cabe. Elimina solo ese iterador para conservar el otro cinco. Si upper_bound apunta al inicio, no existe boleto admisible. Para consultar el primer precio al menos cinco, lower_bound(5) devuelve una de las apariciones de cinco.'},
{title:'Invariantes e iteradores',body:'El árbol balanceado interno conserva la relación de orden definida por el comparador. Antes de dereferenciar, comprueba que el iterador no sea end; antes de retroceder, comprueba que no sea begin. En multiset, erase(valor) borra todas las apariciones equivalentes, mientras erase(iterador) borra una. Utiliza el método miembro lower_bound del conjunto: el algoritmo genérico aplicado a iteradores de árbol puede requerir avance lineal aunque haga pocas comparaciones.'},
{title:'Costo y alcance',body:'Las operaciones principales de búsqueda e inserción cuestan O(log n), y el espacio es O(n). Encontrar el k-ésimo elemento avanzando un iterador cuesta O(k): set estándar no ofrece estadísticas de orden en tiempo logarítmico. Si todos los cambios están en posiciones conocidas, un Fenwick con frecuencias puede ser mejor. Practica procesando presupuestos [6,6,2,10] con los boletos del ejemplo; vendes cinco, cinco, ninguno y ocho. Explica por qué un vector ordenado más borrados intermedios puede terminar costando O(n²) en una secuencia larga.'}
],'¿Qué elimina exactamente una aparición de 5 de un multiset?',['erase(5)','erase(find(5)), si existe','clear()'],1,'erase(valor) elimina todas las claves equivalentes; erase(iterador) elimina únicamente el elemento señalado.'),
G('custom-cpp-stl','Comparadores personalizados en contenedores',['usaco-silver-sorting-custom','usaco-gold-intro-sorted-sets'],['Definir un orden estricto coherente','Entender equivalencia y prioridad'],[
{title:'El orden es parte del modelo',body:'Un registro puede contener puntuación e identificador. Si quieres ordenar por mayor puntuación y, en empate, menor identificador, el comparador debe expresar exactamente esa relación. En sort y set, comp(a,b) significa que a debe aparecer antes que b. La biblioteca necesita un orden débil estricto: ningún elemento debe precederse a sí mismo y las comparaciones deben ser coherentes y transitivas. Usar menor o igual viola la primera condición.'},
{title:'Un empate que cambia el resultado',body:'Considera Ana con 90 puntos e identificador dos, Beto con 90 e identificador uno y Carla con 75 e identificador tres. El orden deseado es Beto, Ana, Carla. Compara primero puntuación con mayor que y después identificador con menor que. Si en un set comparas únicamente puntuaciones, Ana y Beto resultan equivalentes porque ninguna precede a la otra; el conjunto conservará solo uno, aunque sean personas distintas.'},
{title:'Separar set de priority_queue',body:'Un functor puede definir bool operator()(const Registro& a,const Registro& b) const. Mantén el criterio estable mientras los elementos estén almacenados; cambiar datos externos usados por el comparador puede invalidar el orden del contenedor. En priority_queue, el elemento con mayor prioridad queda arriba respecto al orden del comparador: greater<int> crea un mínimo arriba. Comprueba siempre un ejemplo de dos elementos antes de asumir que el mismo criterio sirve igual para ordenar e implementar una cola.'},
{title:'Costo y un ejercicio de diseño',body:'Un comparador O(1) mantiene las cotas habituales: sort O(n log n), operaciones de set O(log n) y push/pop del montículo O(log n). Si comparar examina cadenas largas, ese costo se multiplica y debe contarse. Evita restar enteros para decidir el orden, porque la resta puede desbordarse; compara directamente. Practica almacenando solicitudes por fecha ascendente y urgencia descendente, con identificador como último desempate. Escribe los resultados esperados para tres solicitudes con la misma fecha y verifica irreflexividad y transitividad con casos manuales.'}
],'Si un set compara solo puntuación, ¿qué ocurre con dos personas de 90 puntos?',['Siempre guarda las dos','Las considera equivalentes','Ordena por nombre automáticamente'],1,'Si comp(a,b) y comp(b,a) son ambos falsos, set trata las claves como equivalentes y no admite ambas.' ,true),
G('stacks','Pilas monótonas y vecinos relevantes',['usaco-bronze-intro-ds'],['Encontrar el vecino menor en tiempo lineal','Probar el costo amortizado de una pila'],[
{title:'Eliminar candidatos que ya no sirven',body:'Una pila permite insertar y quitar solo por el extremo superior. Una pila monótona conserva valores en orden creciente o decreciente para responder preguntas sobre el vecino anterior o siguiente que cumple una comparación. La clave no es simplemente ordenar: cada elemento también tiene una posición, y descartamos únicamente candidatos que un elemento más reciente domina para todas las consultas futuras.'},
{title:'El menor anterior más cercano',body:'Para [4,2,5,1,3], queremos en cada posición el índice anterior más cercano con valor estrictamente menor. Al llegar a dos, sacamos cuatro porque no es menor y nunca será mejor candidato que el dos reciente. Al llegar a cinco, el dos queda arriba. Al llegar a uno, salen cinco y dos. Los índices de respuesta, usando cero y −1 para ausencia, son [−1,−1,1,−1,3].'},
{title:'El invariante preciso',body:'Guardamos índices cuyos valores crecen estrictamente desde el fondo. Para procesar x, sacamos mientras el valor superior sea mayor o igual que x, consultamos el superior restante y finalmente insertamos el índice actual. El signo igual importa si la pregunta pide estrictamente menor. El programa lee un arreglo y muestra los índices pedidos. Guardar índices, en lugar de solo valores, permite calcular distancias y resolver empates correctamente.',code:'#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){int n;cin>>n;vector<long long>a(n);vector<int>s;for(int i=0;i<n;i++){cin>>a[i];while(!s.empty()&&a[s.back()]>=a[i])s.pop_back();cout<<(s.empty()?-1:s.back())<<" ";s.push_back(i);}cout<<"\\n";}'},
{title:'Por qué no es cuadrático',body:'Aunque hay un while dentro del recorrido, cada índice se inserta una vez y se elimina a lo sumo una vez: el total es O(n) tiempo y O(n) memoria. Esta amortización aparece también al resolver histogramas y contribuciones de mínimos. Para contar contribuciones con valores repetidos debes repartir los empates, por ejemplo usando estricta de un lado y no estricta del otro. Practica el arreglo [2,2,1]: con menor estricto no hay respuesta en ninguna posición; con menor o igual, la segunda posición sí encuentra la primera.'}
],'¿Por qué una pila monótona tarda O(n) aunque tenga un while interno?',['El while siempre ejecuta una vez','Cada elemento entra y sale a lo sumo una vez','Los datos ya están ordenados'],1,'Sumando todas las iteraciones, hay n inserciones y como máximo n extracciones, independientemente de cómo se distribuyan.'),
G('sliding-window','Ventanas deslizantes y deque monótona',['usaco-silver-two-pointers','usaco-gold-stacks'],['Mantener máximos al mover una ventana','Distinguir ventanas fijas de condiciones monótonas'],[
{title:'Mover dos fronteras sin empezar de nuevo',body:'Una ventana es un segmento contiguo que cambia al avanzar sus extremos. Para una longitud fija k, cada paso elimina el elemento más antiguo e incorpora uno nuevo. Sumas pueden actualizarse restando y sumando; máximos necesitan una estructura que recuerde candidatos. Un multiset ofrece O(log k) por cambio, mientras una deque monótona aprovecha que los índices entran y salen en orden.'},
{title:'Máximos de tres en tres',body:'En [2,1,5,3,4], las ventanas de longitud tres tienen máximos [5,5,5]. Cuando entra cinco, podemos descartar dos y uno: cinco es mayor y permanecerá en las ventanas futuras al menos tanto como ellos. Guardamos índices en orden creciente, con valores decrecientes. El frente representa el máximo. Antes de responder, quitamos del frente los índices que quedaron fuera de [i−k+1,i].'},
{title:'Una deque con dos funciones',body:'Por atrás retiramos candidatos dominados por el valor nuevo; por delante retiramos candidatos vencidos por el movimiento de la frontera. El programa admite 1≤k≤n. Los valores pueden ser negativos: la validez del máximo deslizante no depende de su signo. Para ventanas variables sujetas a suma≤T, en cambio, mover únicamente la izquierda para reparar excesos requiere supuestos como valores no negativos; no transfieras esa condición sin demostrarla.',code:'#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\nint main(){int n,k;cin>>n>>k;if(k<1||k>n)return 0;vector<long long>a(n);deque<int>q;for(int i=0;i<n;i++){cin>>a[i];while(!q.empty()&&q.front()<=i-k)q.pop_front();while(!q.empty()&&a[q.back()]<=a[i])q.pop_back();q.push_back(i);if(i>=k-1)cout<<a[q.front()]<<" ";}cout<<"\\n";}'},
{title:'Costo, alternativas y reto',body:'Cada índice entra y sale una vez, así que el costo total es O(n) y la memoria de la deque O(k), además del arreglo usado en este ejemplo. Una cola hecha con dos pilas puede mantener agregados asociativos cuando no existe una dominancia útil, como máximo común divisor. Practica mínimos de longitud dos en [−1,4,−3,2], que dan [−1,−3,−3]. Después construye un contraejemplo que muestre por qué una ventana para suma máxima con negativos no se arregla usando una regla basada solo en superar un límite.'}
],'¿Qué se elimina por el frente de una deque de máximos?',['Índices que ya salieron de la ventana','Todos los valores negativos','Solo valores menores al nuevo'],0,'El frente elimina candidatos vencidos por posición; los candidatos dominados por valor se eliminan por atrás.'),
G('PURS','Actualización puntual y suma de rango',['usaco-silver-prefix-sums'],['Implementar Fenwick con índices desde uno','Comparar Fenwick y árbol de segmentos'],[
{title:'Cuando los prefijos dejan de ser estáticos',body:'Los prefijos responden sumas en O(1), pero cambiar un valor obliga a modificar muchos prefijos. Un árbol de Fenwick organiza sumas parciales para admitir cambios puntuales y consultas de prefijo en O(log n). Cada posición i, numerada desde uno, guarda la suma de un bloque de longitud lowbit(i)=i&−i que termina en i. Por ejemplo, la posición seis representa las posiciones cinco y seis.'},
{title:'Descomponer una consulta',body:'Para consultar el prefijo de siete, sumamos los bloques almacenados en siete, seis y cuatro: representan [7,7], [5,6] y [1,4], sin repetirse. Luego la suma inclusiva [l,r] es prefijo(r)−prefijo(l−1). Con arreglo [2,4,1,3], la suma [2,4] vale ocho. Si agregamos cinco a la posición tres, el arreglo queda [2,4,6,3] y esa consulta vale trece.'},
{title:'Subir y bajar mediante bits',body:'La consulta avanza i-=i&−i para quitar el bloque derecho ya contado. Una actualización con delta avanza i+=i&−i para visitar todos los bloques que incluyen esa posición. El programa recibe operaciones: 1 índice delta agrega, y 2 l r consulta. Si el enunciado pide asignar un nuevo valor, conserva el anterior y agrega la diferencia; sumar directamente el nuevo valor resolvería una operación distinta.',code:'#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){int n,q;cin>>n>>q;vector<long long>b(n+1);auto add=[&](int i,long long x){for(;i<=n;i+=i&-i)b[i]+=x;};auto sum=[&](int i){long long s=0;for(;i>0;i-=i&-i)s+=b[i];return s;};for(int i=1;i<=n;i++){long long x;cin>>x;add(i,x);}while(q--){int t,l;long long r;cin>>t>>l>>r;if(t==1)add(l,r);else cout<<sum((int)r)-sum(l-1)<<"\\n";}}'},
{title:'Elegir la estructura adecuada',body:'Fenwick requiere O(n) memoria y O(log n) por operación; la construcción mostrada cuesta O(n log n), aunque existe construcción lineal. Un árbol de segmentos también permite estas operaciones y combina otras funciones asociativas como mínimo; la resta de prefijos no funciona para mínimos. Nunca actualices Fenwick en índice cero, pues lowbit(0)=0 produciría un bucle infinito. Practica una estructura de frecuencias para contar cuántos valores son menores que x después de comprimir coordenadas; justifica qué conserva la compresión.'}
],'Si asignas 9 a una posición cuyo valor era 4, ¿qué delta agregas?',['4','5','9','13'],1,'La actualización aditiva debe cambiar 4 en 9: delta=9−4=5.'),
G('dp-trees','Programación dinámica sobre árboles',['usaco-silver-intro-tree','usaco-gold-intro-dp'],['Combinar respuestas de subárboles','Separar estados según la decisión en la raíz'],[
{title:'La ausencia de ciclos separa problemas',body:'Enraizar un árbol divide los vértices bajo cada hijo en subárboles independientes. Muchas decisiones pueden combinarse después de resolver esos hijos, siempre que el estado describa lo que el padre necesita saber. El recorrido posorden procesa primero descendientes y luego el vértice actual. No basta con hacer DFS: debes explicar por qué no existe una interacción olvidada entre subárboles.'},
{title:'Elegir vértices no adyacentes',body:'Buscamos un conjunto independiente de tamaño máximo: no podemos elegir ambos extremos de una arista. Define dp[v][1] como el óptimo del subárbol si eliges v, y dp[v][0] si no lo eliges. Entonces dp[v][1]=1+Σ dp[hijo][0], mientras dp[v][0]=Σ max(dp[hijo][0],dp[hijo][1]). En una estrella con centro y cuatro hojas, elegir el centro da uno; excluirlo permite elegir las cuatro hojas, así que el óptimo es cuatro.'},
{title:'Probar y reconstruir',body:'Si v está elegido, cada hijo está obligado a no estarlo, pero los nietos se deciden dentro de su propio estado. Si v está excluido, cada hijo puede escoger su mejor estado independientemente porque no hay aristas entre subárboles distintos. Esta independencia prueba la transición por inducción sobre el tamaño del subárbol. Para recuperar los vértices elegidos, comienza con el mejor estado de la raíz y transmite a cada hijo la restricción correspondiente.'},
{title:'Costo y trampas del recorrido',body:'Hay dos estados por vértice y cada arista participa una vez al combinar hijos: O(n) tiempo y O(n) memoria. Para un árbol en forma de cadena, una DFS recursiva profunda puede agotar la pila; puedes guardar un orden iterativo y procesarlo al revés. En un grafo con ciclos la misma fórmula cuenta dependencias incorrectamente. Practica con un camino de cinco vértices: elegir posiciones uno, tres y cinco da tres. Después cambia el valor uno por un peso del vértice y adapta la recurrencia al conjunto independiente de peso máximo.'}
],'En una estrella con cuatro hojas, ¿cuál es el conjunto independiente máximo?',['Solo el centro, tamaño 1','Dos hojas, tamaño 2','Todas las hojas, tamaño 4'],2,'Las hojas no son adyacentes entre sí. Elegir las cuatro es válido y supera elegir únicamente el centro.'),
G('all-roots','Reenraizar: respuestas para todos los vértices',['usaco-gold-dp-trees'],['Reutilizar una solución al cambiar la raíz','Separar aportes del subárbol y del exterior'],[
{title:'No hagas una DFS completa por origen',body:'Si necesitas la suma de distancias desde cada vértice de un árbol, ejecutar un recorrido desde cada uno costaría O(n²). El reenraizamiento aprovecha que mover la raíz a un vecino modifica las distancias de forma predecible. Primero eliges una raíz cualquiera y calculas información de subárboles; luego recorres las aristas en sentido descendente para transferir respuestas ya conocidas.'},
{title:'La fórmula de distancias',body:'Sea size[c] el tamaño del subárbol del hijo c y ans[v] la suma de distancias desde v. Al mover el origen de v a c, los size[c] vértices de ese lado se acercan uno y los n−size[c] restantes se alejan uno. Por eso ans[c]=ans[v]+n−2·size[c]. En el camino 0–1–2–3, ans[0]=6 y size[1]=3, así que ans[1]=6+4−6=4. Luego ans[2]=4 y ans[3]=6.'},
{title:'Dos pasadas y un patrón general',body:'En la primera pasada calcula size[v]=1+Σ size[hijo] y down[v]=Σ(down[hijo]+size[hijo]). El valor down de la raíz es su respuesta completa. En la segunda usa la fórmula sobre cada hijo. Para otras funciones, separa la contribución que llega del padre de las que llegan de cada hijo. Prefijos y sufijos de agregados permiten excluir un hijo en O(1) cuando no puedes deshacer una combinación directamente.'},
{title:'Supuestos, costo y práctica',body:'La suma de distancias no ponderadas se resuelve en O(n) tiempo y O(n) memoria. Con peso w en la arista padre–hijo, el cambio es w·(n−2·size[hijo]); usa long long para sumas grandes. No cambies size al cambiar mentalmente la raíz: esos tamaños están definidos respecto a la primera raíz y la fórmula ya lo contempla. Practica una estrella de cinco vértices: el centro suma cuatro y cada hoja suma siete. Después explica cómo guardar los dos mayores aportes de hijos para calcular la distancia al vértice más lejano desde cada raíz.'}
],'Si n=10 y el subárbol del hijo tiene 7 vértices, ¿cuánto cambia la suma al mover la raíz a ese hijo?',['Aumenta 4','Disminuye 4','Aumenta 7','No cambia'],1,'El cambio es n−2·size = 10−14 = −4: siete vértices se acercan y tres se alejan.'),
G('tree-euler','Aplanar árboles con un recorrido de Euler',['usaco-silver-intro-tree','usaco-gold-purs'],['Convertir subárboles en intervalos','Diferenciar tiempo de entrada y recorrido completo'],[
{title:'Un árbol convertido en arreglo',body:'Durante una DFS, todo el subárbol de un vértice se explora antes de regresar a su padre. Si numeras cada vértice cuando entras por primera vez, los vértices de cualquier subárbol ocupan posiciones contiguas. Guarda tin[v] al entrar y tout[v] cuando terminas sus descendientes, usando un contador que aumenta solo al entrar. Entonces el subárbol de v corresponde al intervalo semiabierto [tin[v],tout[v]).'},
{title:'Una numeración concreta',body:'La raíz cero tiene hijos uno y dos; uno tiene hijos tres y cuatro. Visitando primero uno, el orden de entrada es [0,1,3,4,2]. El subárbol de uno ocupa índices [1,4): contiene uno, tres y cuatro. Si sus valores son 5,2,7 respectivamente, sumar ese subárbol equivale a consultar 5+2+7=14 en el arreglo. Un cambio de valor de tres se vuelve una actualización puntual en tin[3]=2.'},
{title:'Qué conserva el aplanamiento',body:'Podemos combinar el orden con Fenwick o árbol de segmentos para consultas de suma de subárbol y cambios puntuales. También u es ancestro de v si tin[u]≤tin[v]<tout[u]. La numeración no convierte automáticamente cualquier camino entre dos vértices en un intervalo; para eso necesitas otra técnica. El recorrido Euler completo que registra retornos al padre tiene 2n−1 apariciones y cumple otra función, como reducir LCA a una consulta de mínimo.'},
{title:'Costo y un reto de implementación',body:'La numeración cuesta O(n), y cada operación posterior de suma o actualización cuesta O(log n) con O(n) memoria. Mantén una convención única: intervalos semiabiertos evitan restas confusas, pero un Fenwick suele usar índices desde uno y requiere convertirlos con cuidado. Un solo vértice debe producir tin=0 y tout=1. Practica agregando un valor a todo un subárbol y consultando un vértice: usa un arreglo de diferencias sobre [tin,tout) y un Fenwick de prefijos. Explica por qué los descendientes reciben exactamente esa actualización y los demás no.'}
],'Con el orden [0,1,3,4,2], ¿qué intervalo semiabierto representa el subárbol de 1?',['[1,3)','[1,4)','[0,4)','[2,5)'],1,'Los índices 1,2,3 contienen 1,3,4; la frontera exclusiva es 4.' ,true),
G('lca-euler','Ancestro común más bajo mediante Euler y RMQ',['usaco-gold-tree-euler'],['Reducir LCA a un mínimo de profundidad','Construir una tabla dispersa estática'],[
{title:'El punto donde se unen dos rutas',body:'El ancestro común más bajo de u y v es el ancestro compartido más profundo cuando el árbol tiene una raíz fija. Es útil para distancias, caminos y consultas sobre relaciones familiares. Registra un recorrido Euler completo: añade un vértice al entrar y vuelve a añadir al padre después de regresar de cada hijo. Guarda la primera aparición de cada vértice y su profundidad en el árbol.'},
{title:'Ejemplo sobre el recorrido',body:'Con raíz cero, hijos uno y dos, y hojas tres y cuatro bajo uno, el recorrido puede ser [0,1,3,1,4,1,0,2,0]. Sus profundidades son [0,1,2,1,2,1,0,1,0]. Entre las primeras apariciones de tres y cuatro, el mínimo de profundidad corresponde a uno, así que LCA(3,4)=1. Entre tres y dos, el mínimo es cero. La DFS debe subir hasta su ancestro compartido antes de entrar al otro subárbol.'},
{title:'Mínimos estáticos con bloques',body:'Una tabla dispersa guarda st[k][i], el índice de menor profundidad en un bloque de longitud 2^k que comienza en i. Combina dos mitades para construir cada bloque. Para consultar [l,r], toma k=floor(log₂(r−l+1)) y compara los bloques que comienzan en l y terminan en r. Pueden solaparse porque mínimo es idempotente: contar un elemento dos veces no cambia el mínimo. Esta consulta de dos bloques no sirve del mismo modo para sumas.'},
{title:'Costo, distancias y práctica',body:'El recorrido ocupa O(n); la tabla usa O(n log n) tiempo y memoria y responde cada LCA en O(1). La distancia sin pesos es depth[u]+depth[v]−2·depth[LCA(u,v)]. No confundas la posición en Euler con la profundidad: un vértice puede aparecer muchas veces con la misma profundidad. Practica LCA(1,4), que debe ser uno, y LCA(v,v), que debe ser v. En el ejemplo, la distancia entre tres y dos es 2+1−2·0=3. Si cambian las aristas del árbol, este preprocesamiento estático deja de ser válido.'}
],'¿Por qué pueden solaparse los dos bloques de una consulta RMQ?',['Porque todo bloque mide uno','Porque mínimo es idempotente','Porque las profundidades son únicas'],1,'min(x,x)=x; una aparición repetida no altera el mínimo. Las profundidades no necesitan ser únicas.' ,true),
G('ternary-search','Búsqueda ternaria y funciones unimodales',['usaco-silver-binary-search'],['Reconocer una función con un solo valle','Distinguir búsqueda real y discreta'],[
{title:'Una forma de función que permite descartar',body:'La búsqueda ternaria encuentra un extremo cuando una función tiene un único comportamiento de descenso y luego ascenso, o la forma invertida para máximos. Para minimizar, compara dos puntos interiores m1 y m2 con m1<m2. Si f(m1)>f(m2), el mínimo no está estrictamente a la izquierda de m1 bajo las hipótesis de unimodalidad; si f(m1)<f(m2), descartas la parte derecha de m2. La prueba depende de la forma de la función, no de que sus valores parezcan suaves.'},
{title:'Un valle fácil de comprobar',body:'Considera f(x)=(x−4)²+3 en [0,12]. El mínimo es f(4)=3. En m1=4 y m2=8 obtenemos tres y diecinueve, de modo que podemos recortar el intervalo derecho. Después de cada comparación conservamos una región que contiene un mínimo. En funciones estrictamente unimodales, la igualdad permite conservar [m1,m2]; con mesetas arbitrarias debes estudiar la garantía exacta, pues una meseta fuera del óptimo puede impedir esa deducción.'},
{title:'Enteros y números reales',body:'En un dominio real, repite un número de iteraciones suficiente para la precisión pedida y evalúa el punto final; la reducción geométrica permite estimar el error en x. En un dominio entero, detente cuando queden pocas posiciones y revísalas todas, evitando que divisiones enteras dejen m1 igual a una frontera indefinidamente. Para una secuencia discretamente convexa, buscar el primer índice donde f(i+1)−f(i) no sea negativo mediante búsqueda binaria suele ser más sencillo.'},
{title:'Costo y un contraejemplo útil',body:'El número de evaluaciones es O(log(rango/precisión)) en reales y O(log n) en enteros, multiplicado por el costo de evaluar f. Si la función tiene varios valles, como una combinación oscilatoria, puedes descartar el mínimo global sin darte cuenta. Practica minimizar max(|x−2|,|x−8|): el centro x=5 alcanza valor tres y la función es convexa. Luego compara con minimizar una función dada solo por una tabla irregular: sin demostrar su forma, la búsqueda ternaria no tiene garantía.'}
],'Para f(x)=(x−4)²+3, ¿cuál es el mínimo?',['x=3, valor 4','x=4, valor 3','x=0, valor 19'],1,'Un cuadrado es no negativo y se hace cero exactamente en x=4; entonces f(4)=3.'),
G('hashing','Huellas de cadenas y colisiones',['usaco-gold-modular'],['Comparar subcadenas con hashes polinomiales','Separar probabilidad de garantía'],[
{title:'Resumir sin conservar toda la información',body:'Un hash asigna una huella corta a una secuencia. Si dos cadenas tienen huellas diferentes, son distintas; si coinciden, podrían ser iguales o una colisión. Esta asimetría es fundamental: un hash no constituye una prueba exacta de igualdad por sí mismo. En concursos, los hashes polinomiales permiten comparar muchas subcadenas rápidamente, pero debes elegir módulos, base y estrategia según la tolerancia a errores del problema.'},
{title:'Construcción por prefijos',body:'Asigna códigos positivos a letras y define H[i+1]=(H[i]·B+código(s[i])) mod M, con H[0]=0. Guarda también potencias de B. La huella de s[l..r) es H[r]−H[l]·B^(r−l), normalizada módulo M. Con B=10, M=101 y códigos [1,2,3], los prefijos son 0,1,12,22. Para las dos últimas cifras, 22−1·100 ≡ 23 módulo 101, que coincide con codificar [2,3].'},
{title:'Consultas y aplicaciones',body:'Después del preprocesamiento, una consulta de hash de subcadena cuesta O(1). Puedes combinar comparaciones de prefijos con búsqueda binaria para hallar una longitud común máxima, o comparar una cadena con su reversa para buscar palíndromos. Incluye la longitud cuando el formato pueda confundir secuencias de distintos tamaños. Dos módulos y una base aleatoria reducen riesgos de colisión, pero no convierten el procedimiento en determinista; si necesitas certeza, verifica candidatos o utiliza algoritmos exactos.'},
{title:'Complejidad y práctica honesta',body:'El preprocesamiento usa O(n) tiempo y memoria. La probabilidad de alguna colisión aumenta cuando realizas muchas comparaciones, por lo que no basta citar el tamaño de un módulo sin considerar el número de consultas. Cuida overflow en productos y normaliza las restas negativas. Practica calculando con el módulo pequeño del ejemplo una colisión deliberada: [1,0,1] codifica 101 y [0] codifica cero. Explica qué parte se arregla almacenando longitud y por qué todavía pueden existir colisiones entre cadenas de igual longitud.'}
],'Si dos hashes coinciden, ¿qué puedes afirmar siempre?',['Las cadenas son iguales','Podría existir una colisión','Las cadenas tienen igual longitud'],1,'La huella tiene menos posibilidades que las cadenas posibles; diferentes cadenas pueden compartir el mismo valor.'),
G('hashmaps','Tablas hash y frecuencias de estados',['usaco-bronze-intro-sets','usaco-silver-prefix-sums'],['Contar coincidencias con unordered_map','Evaluar costo esperado y peor caso'],[
{title:'Asociar una clave a un dato',body:'Un unordered_map relaciona claves con valores mediante una tabla hash. Es útil para frecuencias, estados visitados y memorias cuando el conjunto de claves no se conoce de antemano. No mantiene el orden numérico de las claves ni permite consultar vecinos con lower_bound. El contenedor resuelve colisiones comparando claves: una colisión puede volverlo lento, pero no hace que claves distintas sean confundidas como en una comparación manual de huellas.'},
{title:'Subarreglos con suma objetivo',body:'Sea pref[j] la suma de los primeros j valores. Un subarreglo [i,j) suma T si pref[i]=pref[j]−T. Recorre j de izquierda a derecha y guarda cuántas veces apareció cada prefijo anterior. En [1,−1,1] con T=1, los prefijos son 0,1,0,1. Al llegar a los prefijos uno, cero y uno, encuentras respectivamente 1,0 y 2 coincidencias: hay tres subarreglos. Inicializar la frecuencia de cero en uno cuenta los que empiezan en la primera posición.'},
{title:'Orden de consulta e inserción',body:'Para cada nuevo prefijo s, primero agrega frecuencia[s−T] a la respuesta y después incrementa frecuencia[s]. Insertar primero contaría un subarreglo vacío cuando T=0. Usa long long tanto para prefijos como para el conteo, pues puede haber n(n+1)/2 subarreglos. Con operator[] una clave ausente se inserta con valor cero; para preguntas de existencia sin insertar puedes usar find. Reservar capacidad reduce redistribuciones durante un gran número de inserciones.'},
{title:'Garantías y alternativas',body:'La solución cuesta O(n) esperado con una tabla hash adecuada y O(n) memoria, pero el peor caso puede ser O(n²) por colisiones adversas. Un map ofrece O(n log n) con garantía de árbol balanceado. Si todas las claves se pueden reunir antes, comprimir coordenadas y usar un vector puede ser más predecible. Practica [0,0,0] con objetivo cero: las frecuencias sucesivas producen 1+2+3=6. Explica por qué el método sigue funcionando con negativos mientras una ventana basada únicamente en sumas crecientes no.'}
],'¿Por qué se guarda inicialmente frecuencia[0]=1?',['Para contar subarreglos que comienzan al inicio','Para eliminar valores negativos','Para ordenar las claves'],0,'El prefijo vacío tiene suma cero. Cuando pref[j]=T, su coincidencia representa el subarreglo [0,j).'),
G('meet-in-the-middle','Encontrarse a mitad del camino',['usaco-bronze-complete-rec','usaco-silver-binary-search-sorted-array'],['Reducir una enumeración exponencial por mitades','Combinar resultados sin formar todos los pares'],[
{title:'Cuarenta decisiones todavía son demasiadas',body:'Enumerar todos los subconjuntos de cuarenta elementos exige más de un billón de casos. Sin embargo, dividir los elementos en dos mitades de veinte deja alrededor de un millón de subconjuntos por mitad. Meet in the middle genera resultados parciales y los combina con una búsqueda eficiente. La mejora solo ocurre si evitas probar todas las parejas de resultados, lo que reconstruiría el costo original.'},
{title:'Sumar hasta un objetivo',body:'Con [2,3,5,7] y objetivo diez, divide [2,3] y [5,7]. Las sumas izquierdas son [0,2,3,5] y las derechas [0,5,7,12]. Para cada suma izquierda s, busca 10−s a la derecha. Encuentras s=3 con siete y s=5 con cinco: dos subconjuntos. Debes conservar repeticiones de sumas si cuentas subconjuntos distintos, porque varias elecciones pueden producir el mismo total.'},
{title:'Generar y consultar',body:'Para generar sumas, comienza con cero y, por cada nuevo elemento x, agrega una copia de todas las sumas anteriores más x. Ordena las sumas derechas; equal_range permite contar todas las apariciones del complemento. El programa admite hasta cuarenta elementos y asume que las sumas caben en long long. Valores negativos no rompen este método, ya que la búsqueda opera sobre la lista ordenada de sumas resultantes.',code:'#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nvector<long long> sums(const vector<long long>&a,int l,int r){vector<long long>s{0};for(int i=l;i<r;i++){int z=s.size();for(int j=0;j<z;j++)s.push_back(s[j]+a[i]);}return s;}\nint main(){int n;long long target;cin>>n>>target;if(n<0||n>40)return 0;vector<long long>a(n);for(auto&x:a)cin>>x;auto L=sums(a,0,n/2),R=sums(a,n/2,n);sort(R.begin(),R.end());long long ans=0;for(auto x:L){auto p=equal_range(R.begin(),R.end(),target-x);ans+=p.second-p.first;}cout<<ans<<"\\n";}'},
{title:'Costo y variantes',body:'Generar cuesta O(2^(n/2)) por mitades equilibradas; ordenar y consultar añade un factor O(n), dando O(n·2^(n/2)) tiempo y O(2^(n/2)) memoria. Para maximizar una suma que no exceda T, busca el mayor complemento permitido en vez de uno exacto. No elimines duplicados si representan objetos diferentes y buscas un conteo. Practica [1,1,2] con objetivo dos: hay dos subconjuntos, el objeto de valor dos y la pareja de unos. El subconjunto vacío cuenta cuando el objetivo es cero, salvo que el enunciado lo prohíba.'}
],'¿Cuántos subconjuntos de [2,3,5,7] suman diez?',['1','2','3','4'],1,'Son {3,7} y {2,3,5}; las dos elecciones aparecen al combinar complementos de las mitades.'),
G('gold-conclusion','Taller de cierre de Oro',['usaco-gold-knapsack','usaco-gold-shortest-paths','usaco-gold-purs','usaco-gold-meet-in-the-middle'],['Elegir algoritmos por estructura y límites','Preparar una solución verificable de concurso'],[
{title:'Un catálogo no sustituye al razonamiento',body:'Oro reúne herramientas que cambian la forma de representar un problema: estados de DP, componentes, distancias, intervalos y subconjuntos. Antes de buscar una etiqueta, escribe qué pide exactamente la respuesta y cuáles son las operaciones permitidas. Después identifica la parte que una solución exhaustiva repite. El algoritmo correcto suele aparecer al resumir ese trabajo repetido sin perder información necesaria para el futuro.'},
{title:'Cuatro límites, cuatro rutas',body:'Considera cuatro tareas distintas. Para cuarenta objetos y sumas enormes, meet in the middle puede ser viable. Para mil objetos y capacidad diez mil, una mochila O(nW) hace unos diez millones de transiciones. Para doscientos mil vértices y pesos no negativos, una lista de adyacencia con Dijkstra resulta natural. Para doscientos mil cambios y sumas en un arreglo, Fenwick evita recomputar prefijos. Los números no demuestran por sí solos la solución, pero descartan enfoques incompatibles.'},
{title:'Un protocolo para resolver',body:'Primero produce una solución sencilla para casos pequeños, incluso exponencial. Luego expresa un invariante o recurrencia y explica qué decisiones cubre. Estima tiempo y memoria usando los límites máximos, no solo el ejemplo. Implementa casos base antes de optimizaciones y compara resultados con la solución pequeña en entradas aleatorias. Para un algoritmo probabilístico como hashing, registra explícitamente esa limitación; para uno voraz, busca un argumento de intercambio que justifique cada elección.'},
{title:'Evaluación y siguiente paso',body:'Resuelve tres problemas sin mirar etiquetas: uno de DP, uno de grafos y uno de consultas. Al terminar, redacta qué falló, qué caso lo detectó y por qué la corrección funciona. Como mini examen, decide si BFS resuelve aristas de pesos uno y siete: no, porque las capas cuentan aristas y no costo. Después explica por qué una tabla de mochila con W=10⁹ es inviable aunque n=100. Puedes avanzar a Platino cuando seas capaz de formular y defender una solución nueva con estas herramientas, no solo reproducir una plantilla conocida.'}
],'Con 40 objetos y pesos hasta 10⁹, ¿qué técnica merece explorar para suma de subconjuntos?',['DP por capacidad hasta 4·10¹⁰','Meet in the middle','Ordenar y tomar siempre el menor'],1,'Dos mitades de veinte generan cerca de 2²⁰ sumas cada una, mientras una tabla por capacidad sería demasiado grande.'),
];
